        void ScriptA4Shizune::a4_shizune() {
            SKIP_IF_LOAD_ANOTHER_SCENE(SCRIPT_A4_SHIZUNE);
            ks::SceneManager::set_script(SCRIPT_A4_SHIZUNE);
            IF_NOT_EXIT(ks::SceneManager::init_savedata(ks::progress));
            IF_NOT_EXIT(ks::SceneManager::set(ks::SceneManager("script_a4_shizune")));
        
            IF_NOT_EXIT(a4_shizune_grand_strategy()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_shizune_off_by_one()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_shizune_invasion()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            IF_NOT_EXIT(a4_shizune_parfait()); // INLINE CALL
            IF_NOT_EXIT(ks::SceneManager::timeskip()); // INLINE CALL
            if (ks::progress.refuse_misha) {
                ScriptA4Shizune::a4_shizune__condition_0_0();
            } 
            else {
                ScriptA4Shizune::a4_shizune__condition_0_1();
            } 
            
        
        }
